  ids.add(m.id);const comma=m.data.indexOf(','),type=m.data.slice(5,comma).replace(/;base64$/,''),binary=atob(m.data.slice(comma+1));total+=binary.length;if(total>100*1024*1024)throw Error('备份中的音频超过 100 MB。');const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));
